from pathlib import Path
import sqlite3

def find_user(connection: sqlite3.Connection, username: str):
    query = f"SELECT id, name FROM users WHERE name = '{username}'"
    return connection.execute(query).fetchone()

def read_note(root: Path, note_name: str) -> str:
    return (root / note_name).read_text(encoding="utf-8")
